INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (6, '육수의 표고버섯 기둥, 멸치, 다시마, 양파를 건진 후 표고버섯은 편으로 썰고 청경채는 4cm 크기로 썬다.');
