INSERT INTO recipe_ingredients (recipe_id, ingredient_name, ingredient_amount) VALUES (9, '시금치우유 소스', '5g(1작은술)');
INSERT INTO recipe_ingredients (recipe_id, ingredient_name, ingredient_amount) VALUES (9, '아몬드', '2g(1알)');
