INSERT INTO recipe_step_descriptions (recipe_id, step_descriptions) VALUES (14, '석류는 물 600g와 함께 믹서에 갈고 체에 걸러 즙을 낸다. 그릇에 면을 담고 차갑게 식힌 석류즙을 붓고 견과류, 채 썬 오이를 고명으로 올린다.');
