VALUES (1, 1, '새우 두부 계란찜', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00028_1.png', '찌기', '염증감소', '한식', '보통', 0, 45, '나트륨의 배출을 도와주는 것으로 알려진 칼륨이 풍부한 시금치와 소금, 간장 등의 양념 대신 새우에 들어있는 간으로 맛을 내요.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (2, 1, '부추 콩가루 찜', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00029_1.png', '찌기', '염증감소', '한식', '보통', 0, 45, '콩가루로 버무려 감칠맛과 고소한 맛으로 나트륨 사용량을 줄여보세요. 부추는 피를 맑게 하고 허약 체질을 개선하여 성인병을 예방하는데 효과가 있지만, 알레르기 체질이나 위장이 약한 사람은 부작용이 생길 수 있으니 주의하세요.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (3, 1, '방울토마토 소박이', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00031_1.png', '기타', '염증감소', '한식', '쉬움', 0, 45, '소금에 절이는 오이 대신 방울토마토를 사용하여 나트륨 섭취를 줄였어요. 토마토에는 과일에 대체로 없는 글루탐산이 풍부하여 감칠맛을 내주며, 겉절이 양념과 잘 어우러져 상큼함과 감칠맛을 내주어요.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE);






VALUES (4, 1, '순두부 사과 소스 오이무침', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00032_2.png', '기타', '염증감소', '한식', '보통', 0, 45, '사과에는 팩틴이 풍부하여 체내 나쁜 콜레스테롤을 감소시키고 나트륨 배출을 촉진시켜줘요. 순두부와 사과를 갈아 만든 소스는 맵고 짠 자극적인 간이 아닌 재료 그대로의 새콤달콤한 맛과 깔끔한 맛을 내요.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (5, 1, '된장국', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00037_1.png', '끓이기', '염증감소', '한식', '쉬움', 0, 45, '된장국의 된장 사용량을 줄이기 위해 두부와 감자 등의 재료를 갈아 넣으면 담백한 된장국을 맛볼 수 있어요.
된장의 양을 적게 사용함으로 나트륨 섭취를 줄일 수 있어요.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (6, 1, '표고버섯 청경채국', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00038_1.png', '끓이기', '염증감소', '한식', '보통', 0, 45, '표고버섯 밑둥을 육수에 넣어 감칠맛을 더하고, 멸치와 다시마는 다량의 소금 없이도 국물 맛을 깊게 만들어 주는 역할을 해요. 건표고버섯은 햇볕에 말리는 과정에서 만들어진 비타민 D가 풍부해 칼슘 흡수를 도와 골다공증 예방에 좋은 식품이예요. 생표고버섯에는 비타민 D가 거의 들어있지 않아요.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);




다시마, 양파를 넣어 중간 불에서 10분 정도
끓여 멸치육수를 만든다.');


VALUES (7, 1, '치커리샐러드와 올리브 마늘 소스', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00095_1.png', '기타', '염증감소', '한식', '쉬움', 0, 45, '치커리를 육류와 함께 섭취하면 치커리의 산뜻한 맛으로 입맛을 돋우고 섬유소의 섭취를 늘릴 수 있으며 동맥경화를 예방하는데 도움이 된답니다. 치커리에는 칼륨이 많아 육류나 고나트륨 식사시 함께 섭취하면 체내나트륨 배출에 효과적이에요.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (8, 1, '스트로베리 샐러드', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00087_1.png', '기타', '염증감소', '한식', '쉬움', 0, 45, '딸기는 칼륨이 풍부하여 나트륨 배출에 뛰어나지만 칼슘이 부족한 과일이예요. 그렇기 때문에 칼슘이 풍부한 요거트나 기타 유제품과 함께 섭취하면 좋아요.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (9, 1, '시금치 우유 소스와 그린매쉬드포테이토', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00089_1.png', '찌기', '염증감소', '한식', '쉬움', 0, 45, '시금치에 풍부한 칼륨과 우유의 칼슘은 나트륨 배출을 도와줘요. 감자도 칼륨이 풍부한 채소이지만 감자에 부족한 칼슘을 유제품과 함께 섭취하면 칼슘을 보충 받을 수 있어요.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (10, 1, '버섯구이와 두부타르타르 소스', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00091_1.png', '굽기', '염증감소', '한식', '보통', 0, 45, '새송이 버섯은 칼륨 함량이 높아 육류와 함께 섭취하면 혈중 콜레스테롤 수치를 낮추는데 효과가 있어요.
나트륨이 많은 간장이나 소금 대신 겨자, 레몬 등을 이용한 소스로 나트륨 함량을 줄여보세요.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (11, 1, '구운채소와 간장레몬 소스', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00093_1.png', '굽기', '염증감소', '한식', '쉬움', 0, 45, '채소와 버섯류에는 대부분 나트륨 배출에 효과적인 칼륨이 함유되어 있어 채소를 많이 섭취하는 것이 저나트륨 식단의 기본이에요. 레몬즙은 음식의 짠맛을 감추고 간장과 함께 사용하면 간장의 감칠맛을 상승시키는 효
과도 있어요.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (12, 1, '브로콜리 컬리플라워 샐러드와 두유 요거트 소스', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00094_1.png', '기타', '염증감소', '한식', '쉬움', 0, 45, '브로콜리와 컬리플라워를 데치는 과정에서만 소금을 넣어 맛과 색은 살려주고 소금 사용은 줄였어요, 또한 마요네즈 대신 두유를 사용하면 맛은 고소해지고 나트륨 배설은 증가 시킬 수 있어요.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (13, 1, '오렌지와 당근 만남주스', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00108_1.png', '기타', '염증감소', '한식', '보통', 0, 45, '시판되는 대부분의 주스는 가공되고 농축되는 과정에서 나트륨이 첨가되는 경우가 있어 과일, 채소를 직접 갈아 마시면 나트륨 섭취를 줄일 수 있어요.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);





VALUES (14, 1, '칠곡석류국수', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00111_1.png', '끓이기', '염증감소', '한식', '보통', 0, 45, '견과류에는 불포화 지방산이 풍부하게 함유되어 있어, 고지혈증 등 혈류개선에 효과가 있어 성인병 예방에 좋다. 짠맛을 대신하여 석류의 새콤달콤한 맛을 활용하고, 볶은 견과류로 고소한 맛과 풍미를 더하였다.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);




뺀다.');


VALUES (15, 1, '블랙빈 곤약국수', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00113_1.png', '끓이기', '염증감소', '한식', '쉬움', 0, 45, '검은콩은 안토시아닌 색소를 많이 함유하고 있어 시력회복과 항암작용에 좋다. 나트륨 함량이 높은 소면을 대신하여 실곤약으로 면을 대체함으로써 나트륨과 칼로리의 섭취량을 줄이고, 콩국물에 흑임자와 호두를 넣어 짠맛 대신 고소한 맛과 향을 강조한다.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);





VALUES (16, 1, '닭가슴살 브로콜리 만두', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00114_1.png', '찌기', '염증감소', '한식', '보통', 0, 45, '칼륨 함량이 높은 브로콜리를 사용하여 나트륨 배출을 돕는다. 만두소는 저염간장으로 양념하고 별도로 초간장을 곁들이지 않아 나트륨섭취를 줄인다.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (17, 1, '함초 냉이 국수', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00131_1.png', '끓이기', '염증감소', '한식', '보통', 0, 45, '냉이에 함유된 비타민A와 비타민C는 소화작용을 용이하게 한다. 소금을 대체하여 함초를 사용하고, 멸치와 모시조개, 다시마 등을 사용하여 감칠맛을 더한다.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (18, 1, '된장 두부찌개', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00137_1.png', '끓이기', '염증감소', '한식', '보통', 0, 45, '김치는 물에 헹구어 염분을 제거하고 고추를 넣어 매운 맛과 향을 더한다. 두부는 콩 단백질이 풍부한 식품으로 두뇌발달에 좋다.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (19, 1, '부대된장찌개', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00138_1.png', '끓이기', '염증감소', '한식', '보통', 0, 45, '저염된장과 저염햄을 사용하고 김치는 물에 헹구어 염도를 낮추어 준다.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (20, 1, '양배추감자전', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00181_1.png', '굽기', '염증감소', '한식', '쉬움', 0, 45, '감자와 양배추에는 칼륨이 풍부하게 들어있어 나트륨 배출에 도움을 준다. 양념간장 대신 과일즙을 활용한 폰즈소스를 곁들여 나트륨 섭취량을 줄였다.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (21, 1, '돌나물 샐러드', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00074_1.png', '기타', '염증감소', '한식', '쉬움', 0, 45, '샐러드드레싱에 짠맛을 줄이기 위해 마요네즈 사용량을 줄이고 레몬즙과 청양고추를 혼합하여 드레싱을 만들면 짠맛을 줄이는 효과를 낼 수 있어요. 마요네즈 사용이 지나치면 나트륨과 콜레스테롤의 섭취가 높아지므로 주의하세요.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);




하게 굽는다.');
버무려 접시에 담는다.');


VALUES (22, 1, '석류 보쌈김치', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00159_1.png', '기타', '염증감소', '한식', '보통', 0, 45, '배추는 최소한의 소금으로 절이고 석류 즙으로 새콤한 맛과 향을 더한다. 미네랄, 칼슘, 무기질이 풍부한 석류는 여성질환에 도움을 준다.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (23, 1, '유자 대구조림', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00161_1.png', '끓이기', '염증감소', '한식', '보통', 0, 45, '소스에 유자청으로 향을 더하고 발사믹식초로 상큼함을 더한다. 찜은 재료 본연의 맛을 느낄 수 있는 조리법이며 소스를 찍어먹을 수 있도록 곁들여 내면 나트륨 섭취량을 줄일 수 있다.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






VALUES (24, 1, '파프리카 물김치', 'http://www.foodsafetykorea.go.kr/uploadimg/cook/10_00162_1.png', '기타', '염증감소', '한식', '쉬움', 0, 45, '김치를 절인 후 찬물에 세 번 씻어 소금기를 빼고 기호에 따라 청고추를 넣어 매콤한 맛을 준다.', 0, 0, '2025-05-21 19:19:09', '2025-05-21 19:19:09', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE);






